#include "Script/LuaBindings.h"
#include "Bazzalt/VFX.h"
namespace Bazzalt::Runtime {
void BindLuaVFX(sol::table api){
 api.new_enum("ParticleSimulationBackend","Automatic",ParticleSimulationBackend::Automatic,"CPU",ParticleSimulationBackend::CPU,"GPUAnalytic",ParticleSimulationBackend::GPUAnalytic);
 api.new_enum("ParticleSimulationSpace","Local",ParticleSimulationSpace::Local,"World",ParticleSimulationSpace::World);
 api.new_enum("ParticleEventType","Born",ParticleEventType::Born,"Died",ParticleEventType::Died,"Completed",ParticleEventType::Completed,"Collision",ParticleEventType::Collision);
 auto graph=api.new_usertype<VFXGraph>("VFXGraph",sol::no_constructor);graph["Load"]=&VFXGraph::Load;graph["FromSource"]=&VFXGraph::FromSource;graph["IsValid"]=&VFXGraph::IsValid;graph["GetAssetUUID"]=&VFXGraph::GetAssetUUID;graph["GetError"]=&VFXGraph::GetError;graph["GetDependencies"]=[](const VFXGraph& v){return sol::as_table(v.GetDependencies());};
 auto c=api.new_usertype<ParticleEmitter>("ParticleEmitter",sol::constructors<ParticleEmitter()>(),sol::base_classes,sol::bases<Component>());
 c["Graph"]=&ParticleEmitter::Graph;c["MaterialOverride"]=&ParticleEmitter::MaterialOverride;c["MaxParticles"]=&ParticleEmitter::MaxParticles;c["Seed"]=&ParticleEmitter::Seed;c["SimulationSpeed"]=&ParticleEmitter::SimulationSpeed;c["RateMultiplier"]=&ParticleEmitter::RateMultiplier;c["SizeMultiplier"]=&ParticleEmitter::SizeMultiplier;c["Tint"]=&ParticleEmitter::Tint;c["Space"]=&ParticleEmitter::Space;c["Backend"]=&ParticleEmitter::Backend;c["PlayOnAwake"]=&ParticleEmitter::PlayOnAwake;c["UseUnscaledTime"]=&ParticleEmitter::UseUnscaledTime;c["IsValid"]=&ParticleEmitter::IsValid;
 sol::table operations=api["_ComponentOperations"];auto op=operations.create_named("ParticleEmitter");op["Has"]=[](Entity e){return e.HasComponent<ParticleEmitter>();};op["Get"]=[](Entity e){return ParticleEmitter(e.GetComponent<ParticleEmitter>());};op["Add"]=[](Entity e){return ParticleEmitter(e.AddComponent<ParticleEmitter>());};op["Set"]=[](Entity e,ParticleEmitter c){if(!c.IsValid())throw std::invalid_argument("Invalid ParticleEmitter");e.GetComponent<ParticleEmitter>()=c;};op["Remove"]=[](Entity e){e.RemoveComponent<ParticleEmitter>();};op["IsEnabled"]=[](Entity e){return e.IsComponentEnabled<ParticleEmitter>();};op["SetEnabled"]=[](Entity e,bool enabled){e.SetComponentEnabled<ParticleEmitter>(enabled);};op["Inherited"]=[](Entity)->std::optional<ParticleEmitter>{return {};};
 auto p=api.new_usertype<Particle>("Particle",sol::no_constructor);p["Id"]=&Particle::Id;p["Position"]=&Particle::Position;p["Velocity"]=&Particle::Velocity;p["Age"]=&Particle::Age;p["Lifetime"]=&Particle::Lifetime;p["Size"]=&Particle::Size;p["Rotation"]=&Particle::Rotation;p["Color"]=&Particle::Color;
 auto event=api.new_usertype<ParticleEvent>("ParticleEvent",sol::no_constructor);event["Type"]=&ParticleEvent::Type;event["ParticleId"]=&ParticleEvent::ParticleId;event["Position"]=&ParticleEvent::Position;event["Collider"]=&ParticleEvent::Collider;event["WorldPoint"]=&ParticleEvent::WorldPoint;event["Normal"]=&ParticleEvent::Normal;
 auto stats=api.new_usertype<ParticleStatistics>("ParticleStatistics",sol::no_constructor);stats["Alive"]=&ParticleStatistics::Alive;stats["Capacity"]=&ParticleStatistics::Capacity;stats["Spawned"]=&ParticleStatistics::Spawned;stats["Dropped"]=&ParticleStatistics::Dropped;stats["Time"]=&ParticleStatistics::Time;stats["Playing"]=&ParticleStatistics::Playing;stats["Paused"]=&ParticleStatistics::Paused;stats["Backend"]=&ParticleStatistics::Backend;stats["BackendMessage"]=&ParticleStatistics::BackendMessage;stats["TrailPoints"]=&ParticleStatistics::TrailPoints;stats["CollisionQueries"]=&ParticleStatistics::CollisionQueries;stats["CollisionBudgetMisses"]=&ParticleStatistics::CollisionBudgetMisses;stats["EmittedLights"]=&ParticleStatistics::EmittedLights;
 auto v=api.create_named("VFX");v["Play"]=&VFX::Play;v["Restart"]=&VFX::Restart;v["Pause"]=&VFX::Pause;v["Resume"]=&VFX::Resume;v["Stop"]=[](Entity e,sol::optional<bool> clear){VFX::Stop(e,clear.value_or(true));};v["Clear"]=&VFX::Clear;v["Emit"]=&VFX::Emit;v["SetGraph"]=&VFX::SetGraph;v["Simulate"]=[](Entity e,float time,sol::optional<bool> restart){VFX::Simulate(e,time,restart.value_or(false));};v["GetStatistics"]=&VFX::GetStatistics;v["GetParticles"]=[](Entity e){return sol::as_table(VFX::GetParticles(e));};v["GetEvents"]=[](Entity e){return sol::as_table(VFX::GetEvents(e));};
}
}
